{
  "name": "CryoTel GT 低温制冷机",
  "name_en": "CryoTel GT Cryocooler",
  "manufacturer": "Sunpower",
  "description": "CryoTel GT 是一款紧凑型低温制冷机（斯特林式冷头），带集成控制器，可通过串口监控温度与功率，并在功率或温度两种模式下设置目标值，实现样品、探测器或光学组件的低温维持与稳定。设备支持温度到位判定带宽、恒温开关（thermostat）与停止模式等设置，适用于实验室中的低温测试与长期温控应用。",
  "description_en": "The CryoTel GT is a compact Stirling cryocooler with an integrated controller. It communicates over a serial interface to monitor temperature and power, and supports both temperature and power control modes to maintain cryogenic setpoints for samples, detectors, and optics. It provides an adjustable at-temperature band, thermostat function, and stop modes for laboratory cryogenic experiments and long-term temperature stabilization.",
  "actions": [
    {
      "action_name": "auto-at_temperature_band",
      "description": "获取/设置到温判定带宽（K）。",
      "description_en": "Get/set the at-temperature band (in K)."
    },
    {
      "action_name": "auto-control_mode",
      "description": "获取/设置控制模式（功率/温度）。",
      "description_en": "Get/set the control mode (power/temperature)."
    },
    {
      "action_name": "auto-ki",
      "description": "获取/设置温度控制回路的积分系数（Ki）。",
      "description_en": "Get/set the integral constant (Ki) of the temperature control loop."
    },
    {
      "action_name": "auto-kp",
      "description": "获取/设置温度控制回路的比例系数（Kp）。",
      "description_en": "Get/set the proportional constant (Kp) of the temperature control loop."
    },
    {
      "action_name": "auto-power_max",
      "description": "获取/设置用户定义的最大功率（W）。",
      "description_en": "Get/set the user-defined maximum power (W)."
    },
    {
      "action_name": "auto-power_min",
      "description": "获取/设置用户定义的最小功率（W）。",
      "description_en": "Get/set the user-defined minimum power (W)."
    },
    {
      "action_name": "auto-power_setpoint",
      "description": "获取/设置功率设定值（W，功率模式下生效）。",
      "description_en": "Get/set the power setpoint (W), used in power control mode."
    },
    {
      "action_name": "auto-query",
      "description": "发送查询指令；可选写入值并返回响应/回显。",
      "description_en": "Send a query; optionally write a value and return the response/echo."
    },
    {
      "action_name": "auto-query_multiline",
      "description": "发送查询指令并读取多行响应。",
      "description_en": "Send a query and read a multi-line response."
    },
    {
      "action_name": "auto-reset",
      "description": "恢复设备至出厂默认设置。",
      "description_en": "Reset the device to factory defaults."
    },
    {
      "action_name": "auto-save_control_mode",
      "description": "将当前控制模式保存为默认模式。",
      "description_en": "Save the current control mode as the default."
    },
    {
      "action_name": "auto-sendcmd",
      "description": "发送命令（不要求返回响应）。",
      "description_en": "Send a command without expecting a response."
    },
    {
      "action_name": "auto-stop",
      "description": "获取/设置停止状态（True 停止 / False 运行）。",
      "description_en": "Get/set the stop state (True stop / False run)."
    },
    {
      "action_name": "auto-stop_mode",
      "description": "获取/设置停止模式来源（主机或数字I/O）。",
      "description_en": "Get/set the stop mode source (host or digital I/O)."
    },
    {
      "action_name": "auto-temperature_setpoint",
      "description": "获取/设置温度设定值（K，温度模式下生效）。",
      "description_en": "Get/set the temperature setpoint (K), used in temperature control mode."
    },
    {
      "action_name": "auto-thermostat",
      "description": "获取/设置恒温（thermostat）模式的启用状态。",
      "description_en": "Get/set the thermostat mode enable state."
    },
    {
      "action_name": "auto-errors",
      "description": "获取当前活动的错误代码列表。",
      "description_en": "Get the list of currently active error codes."
    },
    {
      "action_name": "auto-power",
      "description": "获取当前功率（W）。",
      "description_en": "Get the current power (W)."
    },
    {
      "action_name": "auto-power_current_and_limits",
      "description": "获取当前功率及允许的功率上下限（W）。",
      "description_en": "Get the current power and allowable power limits (W)."
    },
    {
      "action_name": "auto-serial_number",
      "description": "获取序列号与硬件版本信息。",
      "description_en": "Get the serial number and revision information."
    },
    {
      "action_name": "auto-state",
      "description": "获取控制器参数与状态列表。",
      "description_en": "Get the controller parameter list and state."
    },
    {
      "action_name": "auto-temperature",
      "description": "获取当前温度（K）。",
      "description_en": "Get the current temperature (K)."
    },
    {
      "action_name": "auto-thermostat_status",
      "description": "获取恒温功能的当前状态（开/关）。",
      "description_en": "Get the current thermostat status (on/off)."
    }
  ],
  "tag_hints": [
    "cryocooler",
    "Stirling cooler",
    "cryogenic temperature control",
    "temperature setpoint",
    "power control mode",
    "serial communication",
    "thermostat",
    "laboratory cryogenics"
  ]
}
